enum LoadingState<T> {
    case idle
    case loading
    case success(T)
    case failure(Error)
}

var state: LoadingState<[User]> = .idle

func fetch() {
    state = .loading
    api.getUsers { result in
        switch result {
        case .success(let users):
            state = .success(users)
        case .failure(let error):
            state = .failure(error)
        }
    }
}

// The compiler ensures you handle every case
switch state {
case .idle:         showPlaceholder()
case .loading:      showSpinner()
case .success(let users): showList(users)
case .failure(let err):   showError(err)
}

enum Response {
    case success(code: Int, body: String)
    case error(code: Int, message: String)
}

let resp: Response = .success(code: 200, body: "{}")

// Full switch with where clause
switch resp {
case .success(let code, _) where code == 200:
    print("OK")
case .success(let code, _):
    print("Success but code: \(code)")
case .error(_, let msg):
    print("Error: \(msg)")
}

// Single-case check with if-case
if case .error(let code, let msg) = resp {
    log("Error \(code): \(msg)")
}

// Pattern matching on ranges
let score = 85
switch score {
case 90...100: print("A")
case 80..<90:  print("B")
default:       print("C or below")
}

indirect enum ArithExpr {
    case number(Double)
    case add(ArithExpr, ArithExpr)
    case multiply(ArithExpr, ArithExpr)
}

func evaluate(_ expr: ArithExpr) -> Double {
    switch expr {
    case .number(let value):
        return value
    case .add(let left, let right):
        return evaluate(left) + evaluate(right)
    case .multiply(let left, let right):
        return evaluate(left) * evaluate(right)
    }
}

// (2 + 3) * 4
let expr: ArithExpr = .multiply(
    .add(.number(2), .number(3)),
    .number(4)
)
print(evaluate(expr))  // 20.0
